import {createRequire} from 'node:module';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

// ajv is CommonJS and its types disagree between jest's ESM loader and NodeNext, so load it by require and type only what is used.
interface ErrorObject {
  keyword: string;
  instancePath?: string;
  dataPath?: string;
  message?: string;
  params: Record<string, unknown>;
}

interface ValidateFunction {
  (data: unknown): boolean;
  errors?: ErrorObject[] | null;
}

interface AjvInstance {
  compile(schema: object): ValidateFunction;
}

type AjvConstructor = new (options: Record<string, unknown>) => AjvInstance;

const ajvModule = createRequire(import.meta.url)('ajv') as AjvConstructor | {default: AjvConstructor};
const Ajv: AjvConstructor = typeof ajvModule === 'function' ? ajvModule : ajvModule.default;

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validate?: ValidateFunction;
}

// ajv 6 reports `dataPath` as `.a.b`; ajv 8 reports `instancePath` as `/a/b`. Either may be the one resolved at runtime.
function errorPath(error: ErrorObject): string {
  if (error.instancePath !== undefined) return error.instancePath || '/';
  const legacy = (error.dataPath ?? '').replace(
    /\['([^']*)'\]|\[(\d+)\]|\.([^.[]+)/g,
    (_m, a, b, c) => `/${a ?? b ?? c}`
  );
  return legacy || '/';
}

function describeError(error: ErrorObject): string {
  const path = errorPath(error);
  if (error.keyword === 'required')
    return `${path}: missing required property '${String(error.params.missingProperty)}'`;
  return `${path}: ${error.message ?? error.keyword}`;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly ajv = new Ajv({strict: false, validateFormats: false, allErrors: true});
  private readonly dynamicValidators = new WeakMap<object, ValidateFunction>();

  private compile(definition: ToolDefinition): ValidateFunction {
    try {
      return this.ajv.compile(definition.inputSchema);
    } catch (error) {
      const reason = error instanceof Error ? error.message : String(error);
      throw new Error(`Invalid inputSchema for tool ${definition.name}: ${reason}`, {cause: error});
    }
  }

  private validatorFor(tool: StoredTool): ValidateFunction {
    if (tool.validate) return tool.validate;
    const schema = this.resolveDefinition(tool.definitionSource).inputSchema;
    let validate = this.dynamicValidators.get(schema);
    if (!validate) {
      validate = this.compile(this.resolveDefinition(tool.definitionSource));
      this.dynamicValidators.set(schema, validate);
    }
    return validate;
  }

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    const validate = typeof definition === 'function' ? undefined : this.compile(resolved);
    this.tools.set(resolved.name, {definitionSource: definition, execute, validate});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Validates input against inputSchema, then runs the tool; see specs/hal-engine-tool-input-validation/spec.md. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const validate = this.validatorFor(tool);
    if (!validate(input)) {
      const problems = (validate.errors ?? []).map(describeError);
      log.warn('tool', 'input rejected', {name, problems});
      return {result: `Invalid input for tool ${name}: ${problems.join('; ')}`};
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}

  describe('function-valued definition whose schema changes between calls', () => {
    const run = async () => {
      const registry = new ToolRegistry();
      let schema: Record<string, unknown> = {type: 'object', properties: {n: {type: 'string'}}, required: ['n']};
      const received: Record<string, unknown>[] = [];
      registry.register(
        () => ({name: 'dynamic_tool', description: 'Dynamic schema', inputSchema: schema}),
        async input => {
          received.push(input);
          return 'ok';
        }
      );

      await registry.execute('dynamic_tool', {n: 'a'});
      schema = {type: 'object', properties: {n: {type: 'number'}}, required: ['n']};
      const rejected = await registry.execute('dynamic_tool', {n: 'a'});
      await registry.execute('dynamic_tool', {n: 2});
      return {rejected, received};
    };

    it('validates a function-valued definition against the schema current at each call', async () => {
      const {rejected} = await run();

      expect(rejected.result).toContain('/n');
    });

    it('runs the executor only for input the current schema accepted', async () => {
      const {received} = await run();

      expect(received).toEqual([{n: 'a'}, {n: 2}]);

